inner join (
    select exam_id, user_id, max(attempt_number) as max_attempt_number
    from exam_user
    where exam_id = #{examId}
    group by exam_id, user_id
    having max(attempt_number) < #{maxAttempts}
) latest on latest.exam_id = eu.exam_id
        and latest.user_id = eu.user_id
        and latest.max_attempt_number = eu.attempt_number
where eu.exam_id = #{examId}
  and eu.exam_status in ('submitted', 'graded')

